// ---------- Strategic review tab (goal, pathway options, validation workshop, five-year plan). Screening-level; generic legacy-asset review practice; the demonstration content is fictional ("Harbourview Works (illustrative)").
// All data lives under r.review (optional; defaults are created on first render; old exports import unchanged).
const RV_TYPES=["Define the closure goal","Validate the current strategy"];
const RV_OBJECTIVES=["Prioritise a legacy-free exit where it is achievable at acceptable cost and risk","Where exit is not achievable, identify lower-cost, lower-risk approaches to closure and post-closure"];
const RV_STAGES=["Background review","Interviews and focus areas","Validation workshop","Strategy report and approvals"];
const RV_DISC=["Technical","Regulatory","Community and social","Commercial and legal","Asset management"];
const RV_CLASSES=["Baseline (do nothing)","Implement current plan","Alternative criteria or regulatory route","Technical alternative","Transfer, divest or repurpose","Exit"];
const RV_STATUS=["Candidate","Eliminated before workshop","Carried to workshop","Validated","Fallback","Rejected"];
const RV_SHOWN=["Carried to workshop","Validated","Fallback"];
const RV_MATRIX=[["duration","Relative duration to closure",["Short","Medium","Long"]],["approval","Relative confidence in approval",["Low","Medium","High"]],["cost","Relative cost",["Low","Medium","High"]],["monitoring","Long-term monitoring",["Yes","No"]],["gaps","Technical data gaps",null],["nextSteps","Next steps",null],["implementation","Implementation considerations",null],["regulatory","Regulatory considerations",null],["community","Community and stakeholder risks",null],["opportunities","Opportunities",null]];
const RV_SCORES=[["approval","Approval confidence",0.25],["time","Time to closure",0.20],["cost","Cost",0.20],["stakeholder","Stakeholder impact",0.15],["risk","Risk reduction",0.20]];
const RV_IMPACT=["None","Some","Most","Unknown"];
const RV_STAKE_ROWS=["Impact on current land users or operations","Property or land value","Regulator approval needed","Local authority approval needed","Landowner or title-holder approval needed","Affected third parties","Transfer of obligations to future owners","Residual contamination or risk remains","Infrastructure and utilities coordination","Cultural and Indigenous interests","Employment and local economy"];
const RV_AGENDA=[[1,"Introduction and safety moment"],[1,"Site and strategy overview: goal, current strategy, review objectives"],[1,"Pre-work readout: technical"],[1,"Pre-work readout: regulatory"],[1,"Pre-work readout: community"],[1,"Clarifications"],[1,"Options validation: first-impression vote"],[1,"Breakout group A: go / no-go on the preferred option"],[1,"Breakout group B: assume validated - how to execute"],[1,"Breakout group C: assume not validated - what instead"],[1,"Report back and second vote"],[2,"Roadmap: gates versus action items"],[2,"Action mapping per gate"],[2,"Most challenging elements and most promising opportunities"],[2,"Close and feedback"]];
const RV_GATES=[["SG1","Internal strategy approval: strategic risk assessment and a 24-month work programme (cost, schedule, resources, engagement plan)",""],["SG2","Project execution plan (phased: Phase I preferred option, Phase II fallback with trigger)","SG1"],["SG3","Stakeholder consultation","SG2"],["SG4","Approval to proceed","SG3"],["SG5","Formal submission to the regulator","SG4"],["SG6","Implementation","SG5"],["SG7","Next strategic review","SG6"]];
const RV_GATE_STATUS=["Not started","In progress","Done","Blocked"];
const RV_LEVERS=[["VL-01","Legacy-free exit","Close out the obligation entirely: relinquishment, completion certificate or equivalent release."],["VL-02","Scope reduction","Remove work that no requirement or risk justifies; right-size covers, treatment and monitoring."],["VL-03","Alternative or risk-based criteria","Replace generic limits with site-specific, receptor-protective criteria where the framework allows."],["VL-04","Duration reduction through exit or shutdown criteria","Define the condition at which treatment or monitoring stops, and the evidence that proves it."],["VL-05","Active-to-passive management","Replace pumped, dosed or staffed systems with passive or semi-passive ones."],["VL-06","Operations, maintenance and reporting optimisation","Reduce frequency, consolidate contracts, automate reporting, retire redundant assets."],["VL-07","Cost recovery or offset from other responsible parties","Pursue contributions from predecessors, partners, insurers or public programmes."],["VL-08","Settlement or liability-transfer strategy","Negotiate a bounded settlement or a transfer of the obligation with the regulator or a third party."],["VL-09","Transfer, divestment or repurposing","Pass the asset to a party that derives value from it, with the obligation attached or released."],["VL-10","Value from land, water or infrastructure","Realise value from land, water rights, power, buildings or access routes."]];
const RV_LEVER_APP=["","Yes","Maybe","No"];
const RV_QUESTIONS={
 "Technical":["Which closure components carry the greatest uncertainty in performance, and what evidence supports the current design basis?","Where does the current plan rely on active treatment or management, and what would be needed to move to passive or walk-away?","Which technical data gaps most constrain the choice between strategy options?","What monitoring results in the last five years have changed, or should have changed, the strategy?","Which assumptions in the cost estimate are conservative by design, and which are inherited without review?","What technical alternatives have been considered and set aside, and why?","What would a failure of the current approach look like, and how would it be detected?"],
 "Regulatory":["Which instruments and conditions define the closure obligations, and which carry an exit or completion criterion?","Where do approved criteria exceed what receptor protection requires, and is a site-specific or risk-based route available?","What is the regulator's current position on relinquishment, transfer or staged release of security?","Which precedents in this jurisdiction support an alternative route, and which argue against it?","What approvals, consultations and timelines would an alternative strategy trigger?","Which compliance risks would persist under each strategy option?","What is the appetite for a phased submission with a defined fallback?"],
 "Community and social":["Who are the affected parties, and how has each been engaged on closure to date?","What outcomes do communities and landholders expect from closure, and how do they differ from the current plan?","Which land uses, access rights and cultural values must the strategy protect or enable?","How would a move from active to passive management be perceived, and what would make it acceptable?","What commitments have been made that constrain the strategy options?","Where are the opportunities for shared value (employment, land, water, infrastructure)?","What would trigger opposition or loss of trust during implementation?"],
 "Commercial and legal":["Which liabilities, indemnities and title conditions would transfer or remain under each option?","Are there other responsible parties from whom costs could be recovered or with whom they could be shared?","What settlement, insurance or liability-transfer mechanisms exist in this jurisdiction?","What contractual or financial-assurance arrangements constrain the timing of a strategy change?","How is the provision built, and which option changes its basis most?","What are the conditions for a divestment, transfer or repurposing to be bankable?","Which legal risks (litigation, enforcement, change in law) differ materially between the options?"],
 "Asset management":["Which assets, infrastructure and services remain in use, and by whom?","What is the condition and remaining life of the water-management and treatment infrastructure?","Which operations, maintenance and reporting activities could be optimised or stopped without raising risk?","What does the five-year spend profile look like, and what drives it?","Which assets have residual value (land, water rights, power, buildings) under each option?","What capability and resourcing would each option require, and is it available?","What is the hand-over readiness of records, drawings and monitoring data?"]};
const rvToday=()=>new Date().toISOString().slice(0,10);
function rvPlusYears(iso,n){ const d=new Date((iso||rvToday())+"T00:00:00Z"); d.setUTCFullYear(d.getUTCFullYear()+(+n||0)); return d.toISOString().slice(0,10); }
function rvNextId(prefix,rows){ let n=rows.length+1, id; do{ id=`${prefix}-${String(n++).padStart(2,"0")}`; }while(rows.some(x=>x.id===id)); return id; }
function rvDefaults(){ return {weights:Object.fromEntries(RV_SCORES.map(s=>[s[0],s[2]])),gates:RV_GATES.map(g=>g[0]),stakeholderRows:RV_STAKE_ROWS.slice(),agenda:RV_AGENDA.length,levers:RV_LEVERS.map(l=>l[0]),objectives:RV_OBJECTIVES.slice()}; }
function rvPathways(r){ const base=Object.keys(PATH_INST); for(const p of Object.keys((r||{}).t2f||{})) if(!base.includes(p)) base.push(p); return base; }
function rvEnsure(r){ const rv=r.review=(r.review&&typeof r.review==="object")?r.review:{}; const t=rvToday();
  if(!RV_TYPES.includes(rv.type)) rv.type=RV_TYPES[1]; if(typeof rv.goal!=="string") rv.goal=""; if(typeof rv.current!=="string") rv.current=""; if(typeof rv.example!=="string") rv.example="";
  if(!Array.isArray(rv.objectives)) rv.objectives=RV_OBJECTIVES.slice(); if(!(+rv.cycleYears>0)) rv.cycleYears=5; if(!rv.nextReview) rv.nextReview=rvPlusYears(t,rv.cycleYears);
  if(!Array.isArray(rv.stages)||rv.stages.length!==RV_STAGES.length) rv.stages=RV_STAGES.map((s,i)=>({id:i+1,name:s,done:false,date:""}));
  for(const k of ["focus","interviews","options","agenda","attendance","gates","actions","leverOpportunities"]) if(!Array.isArray(rv[k])) rv[k]=null;
  rv.focus=rv.focus||[]; rv.interviews=rv.interviews||[]; rv.options=rv.options||[]; rv.attendance=rv.attendance||[]; rv.actions=rv.actions||[]; rv.leverOpportunities=rv.leverOpportunities||[];
  rv.agenda=rv.agenda||RV_AGENDA.map(a=>({day:a[0],item:a[1],lead:"",minutes:""})); rv.gates=rv.gates||RV_GATES.map(g=>({id:g[0],gate:g[1],owner:"",due:"",status:"Not started",depends:g[2]}));
  rv.weights=Object.assign(Object.fromEntries(RV_SCORES.map(s=>[s[0],s[2]])),rv.weights||{}); for(const s of RV_SCORES) if(!(+rv.weights[s[0]]>=0)) rv.weights[s[0]]=s[2];
  if(!Array.isArray(rv.stakeholderRows)) rv.stakeholderRows=RV_STAKE_ROWS.map((l,i)=>({id:"SR-"+String(i+1).padStart(2,"0"),label:l})); rv.stakeholder=rv.stakeholder||{};
  rv.votes=rv.votes||{}; rv.consensus=Object.assign({validated:"",fallback:"",conditions:"",dissent:"",participants:"",date:""},rv.consensus||{}); if(typeof rv.phaseTrigger!=="string") rv.phaseTrigger=""; rv.levers=rv.levers||{}; if(typeof rv.ledgerId!=="string") rv.ledgerId="";
  for(const o of rv.options){ o.matrix=o.matrix||{}; o.scores=o.scores||{}; for(const k of ["name","description","achievesGoal","pathway","eliminationReason","strengths","weaknesses","opportunities","threats","uncertainties","keyOpportunities"]) if(o[k]==null) o[k]=""; if(!RV_CLASSES.includes(o.cls)) o.cls=o.cls||RV_CLASSES[0]; if(!RV_STATUS.includes(o.status)) o.status="Candidate"; }
  return rv; }
const rvCarried=rv=>rv.options.filter(o=>RV_SHOWN.includes(o.status));
const rvValidated=rv=>rv.options.find(o=>o.id===rv.consensus.validated)||rv.options.find(o=>o.status==="Validated")||null;
const rvFallback=rv=>rv.options.find(o=>o.id===rv.consensus.fallback)||rv.options.find(o=>o.status==="Fallback")||null;
function rvIndicator(rv,o){ let sw=0, s=0, n=0; for(const [k] of RV_SCORES){ const v=+((o.scores||{})[k]); const w=+rv.weights[k]||0; if(v>=1&&v<=5){ s+=w*v; sw+=w; n++; } } return n?{score:sw>0?s/sw:0,n}:null; }
function rvThemes(rv){ const m={}; for(const iv of rv.interviews) for(const t of String(iv.themes||"").split(/[,;]/).map(s=>s.trim()).filter(Boolean)){ (m[t]=m[t]||[]).push(iv.id||iv.role||iv.discipline||"interview"); } return Object.entries(m).map(([theme,from])=>({theme,from})); }
function rvInterviewTemplate(disc,r){ const qs=RV_QUESTIONS[disc]||RV_QUESTIONS[RV_DISC[0]]; return [`Interview guide - ${disc} - ${r?r.name+" ("+r.code+")":""}`.trim(),"Purpose: inform the strategic review (closure goal, pathway options, validation workshop, five-year plan). Record the answer, the evidence named and the confidence of the interviewee; note every theme for the workshop agenda.","Interviewee role: ____    Date: ____    Interviewer: ____","",...qs.map((q,i)=>`${i+1}. ${q}\n   Answer / evidence named / confidence:`),"","Themes for the workshop (one line each):","Documents to obtain:"].join("\n"); }
function rvOptionIds(rv){ return rv.options.map(o=>o.id); }
function rvAddOption(r,from){ const rv=rvEnsure(r); const o=from?JSON.parse(JSON.stringify(from)):{name:"",description:"",cls:RV_CLASSES[0],achievesGoal:"Partly",pathway:r.pathway||rvPathways(r)[0],status:"Candidate",eliminationReason:"",strengths:"",weaknesses:"",opportunities:"",threats:"",uncertainties:"",keyOpportunities:"",matrix:{},scores:{}}; o.id=rvNextId("SO",rv.options); if(from){ o.name=(from.name||from.id)+" (copy)"; o.status="Candidate"; } rv.options.push(o); save(); return o; }
function rvDeleteOption(r,id){ const rv=rvEnsure(r); rv.options=rv.options.filter(o=>o.id!==id); delete rv.votes[id]; for(const row of Object.values(rv.stakeholder)) delete row[id]; if(rv.consensus.validated===id) rv.consensus.validated=""; if(rv.consensus.fallback===id) rv.consensus.fallback=""; save(); }
function rvSetVote(r,optId,round,field,value){ const rv=rvEnsure(r); const v=rv.votes[optId]=rv.votes[optId]||{r1:{support:null,neutral:null,oppose:null},r2:{support:null,neutral:null,oppose:null}}; v[round]=v[round]||{support:null,neutral:null,oppose:null}; v[round][field]=value===""||value==null?null:+value; save(); return v; }
function rvSetConsensus(r,field,value){ const rv=rvEnsure(r); rv.consensus[field]=value; if(field==="validated"||field==="fallback"){ const st=field==="validated"?"Validated":"Fallback"; for(const o of rv.options){ if(o.id===value) o.status=st; else if(o.status===st) o.status="Carried to workshop"; } } save(); return rv.consensus; }
function rvSetLever(r,id,app){ const rv=rvEnsure(r); const lever=RV_LEVERS.find(l=>l[0]===id); if(!lever) return null; const lv=rv.levers[id]=Object.assign({applicability:"",evidence:"",effect:"",owner:"",oppId:""},rv.levers[id]||{}); lv.applicability=app||""; const useOpps=Array.isArray(r.opps); const reg=useOpps?r.opps:rv.leverOpportunities;
  if(app==="Yes"||app==="Maybe"){ let o=lv.oppId?reg.find(x=>x.id===lv.oppId):null; if(!o){ o={id:rvNextId(useOpps?`OPP-${r.code}`:`VLO-${r.code}`,reg),type:"Value lever",text:`${lever[1]}: ${lever[2]}`,change:"strategic review lever "+id,status:"Hypothesis",votes:{},source:"Strategic review "+id}; reg.push(o); lv.oppId=o.id; log(r,`Opportunity from value lever ${id} (${lever[1]})`); } else if(o.status==="Parked") o.status="Hypothesis"; }
  else if(lv.oppId){ const o=reg.find(x=>x.id===lv.oppId); if(o&&o.status==="Hypothesis") o.status="Parked"; }
  save(); return lv; }
function rvLeverEntries(r){ const rv=rvEnsure(r); const reg=(Array.isArray(r.opps)?r.opps:[]).concat(rv.leverOpportunities); const ids=new Set(Object.values(rv.levers).map(l=>l.oppId).filter(Boolean)); return reg.filter(o=>ids.has(o.id)); }
function rvActionsCSV(r){ const rv=rvEnsure(r); const q=v=>`"${String(v??"").replace(/"/g,'""')}"`; return ["id,action,gate,year,owner,priority,linked gap or finding"].concat(rv.actions.map(a=>[a.id,a.action,a.gate,a.year,a.owner,a.priority,a.link].map(q).join(","))).join("\n"); }
function rvRecordDecision(r){ const rv=rvEnsure(r); r.decisions=r.decisions||[]; const c=rv.consensus; const v=rvValidated(rv), f=rvFallback(rv); const t=rvToday();
  const entry={question:`Closure goal and pathway for ${r.name}`,options:rv.options.map(o=>o.name||o.id).join(", "),chosen:v?(v.name||v.id):"",rationale:[v?`Validated strategy: ${v.name} (${v.cls}; pathway ${v.pathway||"-"}).`:"No option validated yet.",c.conditions?`Conditions: ${c.conditions}`:"",f?`Fallback: ${f.name}.`:"",rv.goal?`Goal: ${rv.goal}`:"",c.date?`Workshop ${c.date}; participants: ${c.participants||"-"}.`:""].filter(Boolean).join(" "),dissent:c.dissent||"",reversal:rv.phaseTrigger||"",review:rv.nextReview||"",source:"Strategic review"};
  let d=rv.ledgerId?r.decisions.find(x=>x.id===rv.ledgerId):null; if(d) Object.assign(d,entry); else { d=Object.assign({id:rvNextId(`DEC-${r.code}`,r.decisions),date:t,approver:"",status:"Proposed"},entry); r.decisions.push(d); rv.ledgerId=d.id; } log(r,`Strategic review recorded in the decision ledger (${d.id})`); save(); return d; }
function rvApplyPathway(r){ const rv=rvEnsure(r); const v=rvValidated(rv); if(!v||!v.pathway) return false; if(typeof confirm==="function"&&!confirm(`Set the record's pathway to "${v.pathway}" (validated option ${v.name})?`)) return false; r.pathway=v.pathway; log(r,`Pathway set to ${v.pathway} by the strategic review (${v.id})`); save(); return true; }
// ---- markdown generators
const rvMd=v=>String(v??"").replace(/\|/g,"/").replace(/\r?\n+/g," ").trim()||"-";
function rvSiteSummary(r){ const p=r.profile||{}; const cur=(r.currency||"USD").split(" ")[0]; const pick=k=>p[k]||"-"; return [`- Site: ${r.name} (${r.code}); country / jurisdiction: ${r.country||"-"} / ${r.jurisdiction||"-"}`,`- Asset type: ${pick("Asset type")}; closure stage: ${pick("Closure stage")}; ownership: ${pick("Ownership structure")}`,`- Current pathway on the record: ${r.pathway||"-"}; institution-dependent: ${r.institutionDependent?"yes":"no"}; basis: ${r.basis||"-"}`,`- Intended future state (as stated by the owner): ${pick("Intended future state (as stated by the owner - never assumed)")}`,`- Annual recurring cost: ${cur} ${Math.round(+r.recurring||0).toLocaleString()}; provision / ARO: ${cur} ${Math.round(+r.aro||0).toLocaleString()}`]; }
function rvDocsLines(r){ const d=rvDocsLinked(r); return d.length?d.map(x=>"- "+x):["- none linked to this site yet"]; }
function rvDocsLinked(r){ const docs=(typeof library==="function"?library().docs:[]).filter(d=>(d.sites||[]).includes(r.code)).map(d=>`${d.id} ${d.title}${d.date?" ("+d.date+")":""}`); for(const e of (r.evidence||[])) if(!docs.some(x=>x.startsWith(e.id+" "))) docs.push(`${e.id} ${e.title||""}${e.date?" ("+e.date+")":""}${e.grade?" "+e.grade:""}`.trim()); return docs; }
function rvMatrixTable(rv,opts){ const lines=[`| Row | ${opts.map(o=>rvMd(o.name||o.id)).join(" | ")} |`,`|---|${opts.map(()=>"---").join("|")}|`,`| Description | ${opts.map(o=>rvMd(o.description)).join(" | ")} |`]; for(const [k,label] of RV_MATRIX) lines.push(`| ${label} | ${opts.map(o=>rvMd(k==="gaps"?[(o.matrix.gapIds||""),(o.matrix.gaps||"")].filter(Boolean).join("; "):o.matrix[k])).join(" | ")} |`); lines.push(`| Screening indicator (prompt for discussion, never the decision) | ${opts.map(o=>{ const x=rvIndicator(rv,o); return x?x.score.toFixed(2)+" / 5":"-"; }).join(" | ")} |`); return lines; }
function rvStakeTable(rv,opts){ const lines=[`| Consideration | ${opts.map(o=>rvMd(o.name||o.id)).join(" | ")} |`,`|---|${opts.map(()=>"---").join("|")}|`]; for(const row of rv.stakeholderRows){ lines.push(`| ${rvMd(row.label)} | ${opts.map(o=>{ const c=(rv.stakeholder[row.id]||{})[o.id]||{}; return rvMd((c.text||"")+(c.impact?" ["+c.impact+"]":"")); }).join(" | ")} |`); } return lines; }
function rvOptionsBlock(rv,opts){ const out=[]; for(const o of opts){ out.push(`### ${o.id} ${o.name||""} - ${o.cls} - ${o.status}`,o.description||"-",`- Achieves the goal: ${o.achievesGoal||"-"}; pathway: ${o.pathway||"-"}${o.eliminationReason?"; elimination reason: "+o.eliminationReason:""}`,`- Strengths: ${o.strengths||"-"}`,`- Weaknesses: ${o.weaknesses||"-"}`,`- Opportunities: ${o.opportunities||"-"}`,`- Threats: ${o.threats||"-"}`,`- Key uncertainties: ${o.uncertainties||"-"}`,`- Key opportunities: ${o.keyOpportunities||"-"}`,""); } return out; }
function rvPreRead(r){ const rv=rvEnsure(r); const shown=rvCarried(rv); const opts=shown.length?shown:rv.options; const gaps=(r.gaps||[]).filter(g=>(g.status||"Open")!=="Closed"); const L=[`# Validation workshop pre-read - ${r.name} (${r.code})`,`Screening-level. Prepared ${rvToday()}. Review type: ${rv.type}.${rv.example?" Illustrative example: "+rv.example+".":""}`,"","## 1 Site summary",...rvSiteSummary(r),"","## 2 Closure goal and current strategy",`**Closure goal:** ${rv.goal||"(not stated)"}`,"",`**Current strategy:** ${rv.current||"(not stated)"}`,"","Objectives:",...rv.objectives.map(o=>"- "+o),"","## 3 Focus areas","| ID | Focus area | Type | Discipline | Why it matters | Evidence | Challenge in workshop |","|---|---|---|---|---|---|---|",...rv.focus.map(f=>`| ${rvMd(f.id)} | ${rvMd(f.area)} | ${rvMd(f.type)} | ${rvMd(f.discipline)} | ${rvMd(f.why)} | ${rvMd(f.evidence)} | ${rvMd(f.challenge)} |`),"","## 4 Strategy options (with SWOT)",...rvOptionsBlock(rv,rv.options),"## 5 Options overview matrix",...rvMatrixTable(rv,opts),`Screening weights: ${RV_SCORES.map(s=>`${s[1]} ${rv.weights[s[0]]}`).join("; ")}.`,"","## 6 Stakeholder considerations",...rvStakeTable(rv,opts),"","## 7 Open gaps and data gaps",...(gaps.map(g=>`- ${g.id} ${g.topic||g.what||""} (consequence ${g.consequence??"-"}${g.critical?", decision-critical":""}; ${g.status||"Open"})`)),...opts.filter(o=>o.matrix.gapIds||o.matrix.gaps).map(o=>`- ${o.id} data gaps: ${[o.matrix.gapIds,o.matrix.gaps].filter(Boolean).join("; ")}`),"","## 8 Documents linked to the site",...rvDocsLines(r),"","## 9 Interview themes",...(rvThemes(rv).map(t=>`- ${t.theme} (${t.from.join(", ")})`)),"",`Interviews: ${rv.interviews.map(i=>`${i.discipline} - ${i.role} (${i.status||"Planned"}${i.date?", "+i.date:""})`).join("; ")||"-"}`]; return L.map(x=>x===undefined?"":x).join("\n").replace(/\n{3,}/g,"\n\n"); }
function rvReport(r){ const rv=rvEnsure(r); const v=rvValidated(rv), f=rvFallback(rv); const shown=rvCarried(rv); const opts=shown.length?shown:rv.options; const c=rv.consensus; const pr={High:0,Medium:1,Low:2}; const acts=rv.actions.slice().sort((a,b)=>(pr[a.priority]??3)-(pr[b.priority]??3)||(+a.year||9)-(+b.year||9)); const votes=o=>{ const x=rv.votes[o.id]; if(!x) return "-"; const s=rd=>x[rd]?`${x[rd].support??"-"}/${x[rd].neutral??"-"}/${x[rd].oppose??"-"}`:"-"; return `round 1 ${s("r1")}; round 2 ${s("r2")}`; }; const stake=v?rv.stakeholderRows.map(row=>{ const cell=(rv.stakeholder[row.id]||{})[v.id]||{}; return (cell.text||cell.impact)?`- ${row.label}: ${cell.text||""}${cell.impact?" ["+cell.impact+"]":""}`:null; }).filter(Boolean):[]; const levers=RV_LEVERS.filter(l=>["Yes","Maybe"].includes((rv.levers[l[0]]||{}).applicability)).map(l=>`- ${l[1]} (${rv.levers[l[0]].applicability})${rv.levers[l[0]].effect?": "+rv.levers[l[0]].effect:""}`);
  const L=[`# Strategic review - outcome report - ${r.name} (${r.code})`,`> Screening-level: this report assembles the record as entered (statements, options, workshop results, actions). It is a prompt for decision-makers, not a decision; figures are indicative and every rating stays with the person who made it. Prepared ${rvToday()}.${rv.example?" Illustrative example: "+rv.example+".":""}`,"","## Executive summary",`- Review type: ${rv.type}; closure goal: ${rv.goal||"(not stated)"}`,`- Validated strategy: ${v?v.name+" ("+v.cls+"; pathway "+(v.pathway||"-")+")":"none yet"}; fallback: ${f?f.name:"none"}`,`- Workshop: ${c.date||"-"}; participants: ${c.participants||"-"}${c.conditions?"; conditions: "+c.conditions:""}`,`- Phase trigger (Phase I to Phase II): ${rv.phaseTrigger||"-"}`,`- Next strategic review: ${rv.nextReview||"-"} (cycle ${rv.cycleYears} years)`,"","| Option | Key uncertainties and threats | Key opportunities |","|---|---|---|",...rv.options.map(o=>`| ${rvMd(o.name||o.id)} (${o.status}) | ${rvMd([o.uncertainties,o.threats].filter(Boolean).join("; "))} | ${rvMd([o.keyOpportunities,o.opportunities].filter(Boolean).join("; "))} |`),"","## Background and current strategy",...rvSiteSummary(r),"",`Current strategy: ${rv.current||"(not stated)"}`,"","Objectives of the review:",...rv.objectives.map(o=>"- "+o),"","Focus areas:",...rv.focus.map(x=>`- ${x.id} ${x.area} (${x.type}; ${x.discipline}): ${x.why}`),"","## Strategy elimination and validation","| Option | Class | Status | Achieves the goal | Elimination reason or validation note | Votes (support/neutral/oppose) |","|---|---|---|---|---|---|",...rv.options.map(o=>`| ${rvMd(o.name||o.id)} | ${rvMd(o.cls)} | ${rvMd(o.status)} | ${rvMd(o.achievesGoal)} | ${rvMd(o.status==="Eliminated before workshop"||o.status==="Rejected"?o.eliminationReason:(o.id===(v||{}).id?"Validated in the workshop"+(c.conditions?" subject to: "+c.conditions:""):o.id===(f||{}).id?"Held as fallback":o.eliminationReason))} | ${votes(o)} |`),"",c.dissent?`Dissent recorded: ${c.dissent}`:"No dissent recorded.","","## Threats and opportunities for the validated strategy, with mitigations",...(v?[`Validated option: ${v.name}`,"",`Threats and weaknesses: ${[v.threats,v.weaknesses].filter(Boolean).join("; ")||"-"}`,`Key uncertainties: ${v.uncertainties||"-"}`,`Opportunities: ${[v.opportunities,v.keyOpportunities].filter(Boolean).join("; ")||"-"}`,`Mitigations and conditions: ${[c.conditions,v.matrix.nextSteps,v.matrix.implementation,v.matrix.regulatory].filter(Boolean).join("; ")||"-"}`,`Community and stakeholder risks: ${v.matrix.community||"-"}`]:["No option validated yet."]),"","## Recommended actions prioritised for the five-year plan","| ID | Action | Gate | Year | Owner | Priority | Linked gap or finding |","|---|---|---|---|---|---|---|",...acts.map(a=>`| ${rvMd(a.id)} | ${rvMd(a.action)} | ${rvMd(a.gate)} | ${rvMd(a.year)} | ${rvMd(a.owner)} | ${rvMd(a.priority)} | ${rvMd(a.link)} |`),"","## Next steps and gates","| Gate | Description | Owner | Due | Status | Depends on |","|---|---|---|---|---|---|",...rv.gates.map(g=>`| ${rvMd(g.id)} | ${rvMd(g.gate)} | ${rvMd(g.owner)} | ${rvMd(g.due)} | ${rvMd(g.status)} | ${rvMd(g.depends)} |`),"","## Additional considerations",...(stake.length?["Stakeholder considerations for the validated option:",...stake]:["Stakeholder considerations: none recorded for the validated option."]),"",...(levers.length?["Value levers assessed as applicable or possibly applicable:",...levers]:["Value levers: none assessed as applicable yet."]),"","## Appendices","### A Pre-workshop evaluation","Focus areas:","| ID | Focus area | Type | Discipline | Why it matters | Evidence | Challenge in workshop |","|---|---|---|---|---|---|---|",...rv.focus.map(x=>`| ${rvMd(x.id)} | ${rvMd(x.area)} | ${rvMd(x.type)} | ${rvMd(x.discipline)} | ${rvMd(x.why)} | ${rvMd(x.evidence)} | ${rvMd(x.challenge)} |`),"","Interview programme:","| ID | Discipline | Role | Date | Status | Themes |","|---|---|---|---|---|---|",...rv.interviews.map(i=>`| ${rvMd(i.id)} | ${rvMd(i.discipline)} | ${rvMd(i.role)} | ${rvMd(i.date)} | ${rvMd(i.status)} | ${rvMd(i.themes)} |`),"","Options with SWOT:",...rvOptionsBlock(rv,rv.options),"### B Agenda and attendance",...rv.agenda.map(a=>`- Day ${a.day}: ${a.item}${a.lead?" ("+a.lead+")":""}`),"","Attendance:",...(rv.attendance.length?rv.attendance.map(a=>`- ${a.role||"-"}${a.organisation?", "+a.organisation:""}${a.name?" - "+a.name:""}`):["- none recorded"]),"","### C Options matrix",...rvMatrixTable(rv,opts),"","### D Stakeholder matrix",...rvStakeTable(rv,opts),"","### E Document library",...rvDocsLines(r)]; return L.join("\n").replace(/\n{3,}/g,"\n\n"); }
