  rv.goal="Harbourview Works (illustrative): reach a condition within 15 years in which the former processing area and the tailings facility can pass to a successor land manager with no active water treatment and a bounded monitoring obligation."; rv.current="Implement the approved closure plan: engineered cover on the tailings facility, active water treatment to the current discharge limits for an open-ended period, and monitoring under the existing permit with no end criterion.";
  rv.cycleYears=5; rv.nextReview="2031-10-15"; rv.stages[0].done=true; rv.stages[0].date="2026-06-30"; rv.stages[1].done=true; rv.stages[1].date="2026-09-12"; rv.stages[2].done=true; rv.stages[2].date="2026-10-15";
