  const st=(row,opt,text,impact)=>{ (rv.stakeholder[row]=rv.stakeholder[row]||{})[opt]={text,impact}; }; st("SR-01","SO-02","Plant site stays in operation","Some"); st("SR-01","SO-03","Plant site released after step-down","Most"); st("SR-01","SO-04","Passive cells take land on the lower terrace","Some"); st("SR-03","SO-02","None beyond the current permit","None"); st("SR-03","SO-03","New criteria approval","Most"); st("SR-03","SO-04","Permit variation","Some"); st("SR-08","SO-02","Treated discharge continues","Some"); st("SR-08","SO-03","Residual load within receptor-protective criteria","Some"); st("SR-08","SO-04","Residual risk in wet years","Unknown"); st("SR-10","SO-03","Access to the western lease sought by the community","Some"); st("SR-11","SO-02","Plant operations retain local jobs","Some"); st("SR-11","SO-03","Fewer operating jobs; stewardship programme","Some");
  rv.votes={"SO-02":{r1:{support:3,neutral:5,oppose:4},r2:{support:2,neutral:3,oppose:7}},"SO-03":{r1:{support:6,neutral:4,oppose:2},r2:{support:9,neutral:2,oppose:1}},"SO-04":{r1:{support:3,neutral:6,oppose:3},r2:{support:4,neutral:6,oppose:2}}};
  rv.consensus={validated:"SO-03",fallback:"SO-04",conditions:"Receptor study confirms protection at the downstream boundary; regulator pre-engagement within 12 months; a visible stewardship programme for the western lease.",dissent:"One technical participant preferred the current plan until the source term is re-modelled.",participants:"12 (owner closure team 5, technical specialists 4, regulatory specialist 1, community relations 1, facilitator 1)",date:"2026-10-15"};
  rv.attendance=[{name:"",role:"Closure lead (owner)",organisation:"Owner",day1:"Y",day2:"Y"},{name:"",role:"Site closure engineer",organisation:"Owner",day1:"Y",day2:"Y"},{name:"",role:"Permitting specialist",organisation:"Adviser",day1:"Y",day2:"Y"},{name:"",role:"Community relations lead",organisation:"Owner",day1:"Y",day2:"N"},{name:"",role:"Facilitator",organisation:"Adviser",day1:"Y",day2:"Y"}];
  rv.gates[0].status="Done"; rv.gates[0].owner="Closure lead"; rv.gates[0].due="2026-11-30"; rv.gates[1].status="Done"; rv.gates[1].owner="Closure lead"; rv.gates[1].due="2027-01-31"; rv.gates[2].status="In progress"; rv.gates[2].owner="Community relations lead"; rv.gates[2].due="2027-06-30"; rv.gates[4].owner="Permitting specialist"; rv.gates[4].due="2028-03-31"; rv.gates[6].due="2031-10-15";
  rv.actions=[{id:"SA-01",action:"Scope and commission the downstream receptor study",gate:"SG2",year:"1",owner:"Site closure engineer",priority:"High",link:"GAP-DEMO-02"},{id:"SA-02",action:"Pre-engage the regulator on site-specific criteria and staged security release",gate:"SG3",year:"1",owner:"Permitting specialist",priority:"High",link:"FA-02"},{id:"SA-03",action:"Design the visible stewardship programme for the western lease with the community",gate:"SG3",year:"2",owner:"Community relations lead",priority:"Medium",link:"FA-03"}];
  rv.phaseTrigger="Phase II (passive management fallback) starts if the site-specific criteria are not approved within 36 months of submission, or if the receptor study shows protection cannot be demonstrated.";
