  onk("#rvrep",()=>{ $("#rvreptxt").value=rvReport(r); }); onk("#rvrepcopy",()=>{ const t=$("#rvreptxt"); if(!t.value) t.value=rvReport(r); copy(t); }); onk("#rvrepdl",()=>dl(`${r.code}-strategic-review-report.md`,rvReport(r),"text/markdown"));
